pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _test(uint256 _val) internal {
        try c.Initialized() {} catch { return; }
        bool revert1 = false;
        try c.SetMinSum(_val) { revert1 = false; } catch { revert1 = true; }
        assertTrue(revert1 == true);
    }

    function testFuzz_test(uint256 _val) public {
        _test(_val);
    }

    receive() external payable {}
}
